INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-1-0', 'doc-new-book-1', NULL, 0, 'بنیادی‌ترین منبع نظریِ مفهوم «سرمایه‌داری نظارتی» که در سایت به‌عنوان مدخل ۱۱۸ آمده است؛ Zuboff در آن قدرت‌های جدید داده‌محور، محصولات کنشی (actionable products) و بازارهای پیش‌بینی آینده‌رفتار را تحلیل می‌کند. بعداً در مقالات Big Other (2015) و Surveillance & Society (2019) گسترش یافت.', '59f99d1ea94a5ef75bd45c2402d908ff76ad8e1ad41ac6a0248a66adb9242112', 521, 'ch-doc-new-book-1-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-10-0', 'doc-new-book-10', NULL, 0, 'مرجع‌ترین کتابِ مفهوم «حباب فیلتر»؛ پارایزر نشان می‌دهد الگوریتم‌های شخصی‌سازی اینترنت چگونه هر کاربر را در دنیای اطلاعاتی جداگانه‌ای محصور می‌کنند. پایه‌ی مدخل ۱۱۲ (حباب فیلتر) و ۱۱۳ (اتاق پژواک).', '3468441e19949933adee5ba0fd19388e7224e30fe40084f655096ef63554e90a', 358, 'ch-doc-new-book-10-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-11-0', 'doc-new-book-11', NULL, 0, 'پراستنادترین مقاله‌ی تجربیِ مقایسه‌ی انتشار اخبار درست و نادرست در Twitter؛ یافته‌ی محوری: اخبار نادرست حدود ۶ برابر سریع‌تر و گسترده‌تر از اخبار درست پخش می‌شود. پایه‌ی تجربیِ مدخل ۶۷۴ (مدل اشاعه اطلاعات جعلی). (تأییدشده با Crossref — Science, vol 359, iss 6380, p 1146-1151)', '70935d4f17bb3a76fe556b187e3cb4200d84e687f87e09f7b68f2de65eaddc83', 501, 'ch-doc-new-book-11-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-12-0', 'doc-new-book-12', NULL, 0, 'پراستنادترین مقاله‌ی اقتصادِ خبرِ جعلی؛ برآورد اثر اخبار جعلی در انتخابات ۲۰۱۶ آمریکا (حدود ۱/۲ رأی) و مکانیزم‌های پخش آن در شبکه‌های اجتماعی. پایه‌ی اقتصادیِ مدخل ۵۳۰ و ۶۷۴. (تأییدشده با Crossref — JEP, vol 31, iss 2, p 211-236)', 'a517833add90e33527dc662217c1d225276f7104dc272cc63114b284079993af', 416, 'ch-doc-new-book-12-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-13-0', 'doc-new-book-13', NULL, 0, 'آزمایش‌محورترین مقاله‌ی «اتاق پژواک»؛ با استفاده از فیس‌بوک نشان می‌دهد کاربران در فضای آنلاین با طیف ایدئولوژیک تنگ‌تری از اخبار مواجه می‌شوند نسبت به رسانه‌های سنتی. پایه‌ی تجربیِ مدخل ۱۱۳ و ۱۱۲. (تأییدشده با Crossref — Science, vol 348, iss 6239, p 1130-1132)', '34b6028aab3f69f2258955ebee3cd0c980a3b7243ff5e4e1a416a78c7989479d', 476, 'ch-doc-new-book-13-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-14-0', 'doc-new-book-14', NULL, 0, 'مهم‌ترین مدل نظریِ «ارتباطات اسلامی/بومی» که توسط یک نظریه‌پرداز ایرانی (مولانا) مطرح شده؛ پنج بُعد: ارتباط خودباخودی، ارتباط با خدا، ارتباط بین‌فردی، ارتباط با طبیعت و ارتباط اجتماعی. منبع اصلیِ مدخل ۲۸۰ (نظریه خودتعیینی) و بافت ایرانی/اسلامی سایت. (تأییدشده با Crossref — JIC, vol 25, iss 1, p 3-33)', 'e74c8bdf09ede3a644421f1470c94a3a331756de03743042fbec24b87ae36c41', 547, 'ch-doc-new-book-14-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-15-0', 'doc-new-book-15', NULL, 0, 'مهم‌ترین مقاله‌ی نظریِ «غرب‌زدایی‌کردنِ نظریه رسانه» از منظر ارتباطات اسلامی؛ استدلال می‌کند «ارتباطات اسلامی» می‌تواند نظریه‌ای مستقل باشد نه صرفاً تطبیق نظریه‌های غربی. منبع اصلیِ مدخل ۹۵ (شرق‌شناسی و نظریه پسااستعماری رسانه). (تأییدشده با Crossref — MCS, vol 25, iss 3, p 415-422)', '4dfd8c05a526c7ed9fd0f9c6b5e1a4c9a343755ad6b4ce9fb9d33ca47039fbba', 514, 'ch-doc-new-book-15-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-16-0', 'doc-new-book-16', NULL, 0, 'مهم‌ترین اثر تاریخیِ سینمای ایران در ۴ جلد؛ تحلیل بازنمایی هویت، تاریخ و مدرنیته در سینمای ایران. منبع اصلیِ تاریخ رسانه/بازنمایی در بافت ایرانی. (تأییدشده با Crossref — Duke UP, 4 volumes)', '88596634c38399afb0a5353b247ec6512a08a6331a1d135b65b2adfa684928e9', 343, 'ch-doc-new-book-16-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-17-0', 'doc-new-book-17', NULL, 0, 'کلاسیکِ ارتباطات بین‌المللی از دیدگاه یک نظریه‌پرداز ایرانی (نسخه‌ی ۱۹۹۷)؛ تحلیل نظم نوین جهانی اطلاعات و ارتباطات و نقش رسانه‌ها در ساخت جهانی‌شدن. منبع اصلیِ مدخل ۴۰۳ (نظم نوین جهانی اطلاعات و ارتباطات) و ۵۱۳ (نظریه نظام جهانی اطلاعات).', '29b12c3892fe50c1dcc961c0ea57b2100172f0c64301eaf0feabfd5386ebf6b7', 432, 'ch-doc-new-book-17-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-18-0', 'doc-new-book-18', NULL, 0, 'ادامه‌ی اثر کلاسیکِ مولانا؛ تحلیل گذار در ارتباطات جهانی و پرسش از آینده‌ی تنوع فرهنگی در برابر یکسان‌سازی. منبع اصلیِ مدخل ۴۰۳ و تکمیل‌کننده‌ی ۵۱۳.', '4cd478f183a1bcc35dfebe29f513e947f2432e1071395e278ec04872dc8c55aa', 269, 'ch-doc-new-book-18-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-19-0', 'doc-new-book-19', NULL, 0, 'مهم‌ترین تحلیلِ فلسفه‌ی علمِ پسا-حقیقت؛ Fuller پسا-حقیقت را «استفاده‌ی ابزاری از احساسات و روایت برای شکل‌دهی به حقیقت» تعریف می‌کند. مکملِ نظریِ McIntyre (#4) و d''Ancona (#5) — پراستناد در مطالعات پسا-حقیقت.', '8eb9322749bbe9b2c056501bb38837da37cedb50ad965916e582563025d3da26', 378, 'ch-doc-new-book-19-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-2-0', 'doc-new-book-2', NULL, 0, 'بنیادی‌ترین منبع نقدِ الگوریتم‌های جستجو از منظر نژاد و جنسیت؛ پراستناد در مطالعات الگوریتم انتقادی و عدالت داده. این کتاب مستقیماً با مدخل ۲۸۱ (الگوریتم‌های سرکوب) هم‌نام است.', '2a13be796bdc812739dc92f8aaadd657a054aab10be57f268faf6d816f919084', 320, 'ch-doc-new-book-2-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-20-0', 'doc-new-book-20', NULL, 0, 'مقاله‌ی بنیادینِ Zuboff (پیش از کتاب #1) که مفهوم «بزرگ‌دیگری» (Big Other) و سرمایه‌داری نظارتی را مطرح کرد؛ پیش‌بینی تمدن اطلاعاتی زیر کنترل نهادهای کنشی. منبع اصلیِ مدخل ۲۷۲ (حکمرانی‌مندی و قدرت زیستی) و ۲۸۵ (داده‌نظارتی). (تأییدشده با Crossref — Journal of Information Technology, 2015)', '936a829fe0d8a77a37343a69473f3e767b3db5ae135b87aea694ebb45688ce65', 525, 'ch-doc-new-book-20-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-3-0', 'doc-new-book-3', NULL, 0, 'یکی از تأثیرگذارترین آثار مطالعات انتقادی اقتصاد پلتفرمی؛ تحلیل سرمایه‌گذاری‌های پلتفرمی، جریان‌های درآمدی و رقابت بین پلتفرم‌های بزرگ. پایه‌ی مفهومی مدخل ۲۲۲ (سرمایه‌داری پلتفرمی) و ۱۱۷ (جامعه پلتفرمی).', '9272a68cf16b91769d54215e2e895d43ad38d57a6e158bc9f609b39be2fa566f', 369, 'ch-doc-new-book-3-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-4-0', 'doc-new-book-4', NULL, 0, 'مهم‌ترین کتاب فلسفیِ مفهوم «پسا-حقیقت»؛ McIntyre استدلال می‌کند پسا-حقیقت وضعی طبیعی نیست، بلکه یک استراتژی گمراه‌سازی عمدی و سیستماتیک است. پایه‌ی نظریِ مدخل ۴۳۸ (عصر پسا-حقیقت) و ۶۷۳ (نظریه پستحقیقت).', 'e4dc9215c84f00e825f143a4c9b19380dab066c7f73abd4b922324424f7583f2', 367, 'ch-doc-new-book-4-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-5-0', 'doc-new-book-5', NULL, 0, 'کتاب مرجعِ ژورنالیستیِ پسا-حقیقت؛ تحلیل تاریخچه‌ی مفهوم (از ۱۹۷۴ تا ۲۰۱۶) و نقش رسانه‌های دیجیتال و شبکه‌های اجتماعی در ساخت پسا-حقیقت. مکمل McIntyre و منبع اصلی مدخل ۵۳۰.', '23e83ad38ce3f6eceec17d3b6ad0bbda3fcf5937e8c1ddf51fc16e399465248b', 310, 'ch-doc-new-book-5-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-6-0', 'doc-new-book-6', NULL, 0, 'مرجع‌ترین کتاب مطالعات میم‌ها؛ چارچوب «تولید معنایی میم‌ها» (meaning-making memes) و طبقه‌بندی میم‌های متحرک، ایستا و متنی. پایه‌ی مدخل ۳۳۰ (اثر هنری در عصر بازتولید مکانیکی — بازسازی و بازتولید دیجیتال).', '6dbfb3e3849c155ccd25292c39d33cc00e0afb6310cce3996c1997ec327cabe5', 370, 'ch-doc-new-book-6-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-7-0', 'doc-new-book-7', NULL, 0, 'کتاب درسیِ مرجعِ فرهنگ دیجیتال؛ تحلیل تغییرات هویت، مشارکت و جریان فرهنگی در عصر دیجیتال. پایه‌ی مفهومی مدخل ۲۲۵ (فرهنگ الگوریتمی) و ۱۱۷ (جامعه پلتفرمی).', '0e06f7b807efefc0b84197ca29a2dc52fa13083acf269d3af8f52b84377b7ce9', 278, 'ch-doc-new-book-7-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-8-0', 'doc-new-book-8', NULL, 0, 'کتاب مرجعِ ژورنالیستیِ اخبار جعلی؛ بررسی تاریخچه، پیدایش، اشکال و عواقب fake news با تأکید بر سیاست و انتخابات. مکمل تجربیِ مدخل‌های ۵۳۰، ۶۷۴ و ۷۰۵.', 'd24ce51cda93e97284864466180e1f9877526922bd8760210791af33ea7ec8b7', 269, 'ch-doc-new-book-8-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-book-9-0', 'doc-new-book-9', NULL, 0, 'مرجع‌ترین کتاب تاریخیِ «اقتصاد توجه»؛ از کافه‌های عصری تا گوگل، تاریخ رقابت بر سر توجه انسان را روایت می‌کند. مکمل مدخل‌های ۳۲ (اقتصاد توجه) و ۳۸۳/۵۰۲ (تاجران توجه).', '329ff2830dd1aede62a1831724ab0c44ceb9f38a43a39aebbde7fe4f985abf0c', 300, 'ch-doc-new-book-9-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-1-0', 'doc-new-journal-1', NULL, 0, 'New Media & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات رسانه‌های نو است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش‌های رسانه‌های دیجیتال، فناوری و جامعه و تحلیل رسانه‌های نو به‌شمار می‌رود. با ISSN 1461-4448 (چاپی) و 1461-7315 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده است و داده‌های آن از CrossRef اعتبارسنجی شده است.', '8685bdaff2ba3b4e06c8b46b015a476bf1fa7d351ae0254291254cdd8ff6a838', 709, 'ch-doc-new-journal-1-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-10-0', 'doc-new-journal-10', NULL, 0, 'Rasaneh-ye Farhang (رسانه و فرهنگ) مجلهٔ شناخته‌شده‌ی ایرانی در حوزه‌ی رسانه و فرهنگ، ارتباطات و مطالعات فرهنگی است که ناشر آن احتمالاً دانشگاه تهران است (نیازمند تأیید). این مجله مرجع اصلی «رسانه و فرهنگ» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ناشر، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', '38c4b6029233bad5e15545ee79463fc24a16d7deda848323a9b48689dae768a3', 825, 'ch-doc-new-journal-10-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-11-0', 'doc-new-journal-11', NULL, 0, 'مطالعات فرهنگ و ارتباطات مجلهٔ فارسی در حوزه‌ی فرهنگ، ارتباطات، مطالعات فرهنگی و رسانه است که ناشر آن احتمالاً پژوهشگاه فرهنگ، هنر و ارتباطات است (نیازمند تأیید). این مجله مرجع اصلی «مطالعات فرهنگی» در بافت ایرانی به‌شمار می‌رود. هشدار: ممکن است با مجلهٔ انگلیسی «Journal of Culture-Communication Studies (JCCS)» (ردیف ۲۴ فهرست ۲۵ مجلهٔ موجود) تکراری باشد و در صورت تأیید تداخل باید حذف شود. پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', '6a0233c45cc38e3a9ceaa9591ec0746a787d8557520e3716612d916682a5a5da', 832, 'ch-doc-new-journal-11-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-12-0', 'doc-new-journal-12', NULL, 0, 'فرهنگ رسانه (نشریهٔ انجمن فرهنگی رسانه ایران) مجلهٔ فارسی در حوزه‌ی فرهنگ رسانه و ارتباطات است که توسط انجمن فرهنگی رسانه ایران منتشر می‌شود. این کم‌اعتبارترین مورد فهرست ۱۵ مجلهٔ جدید است؛ اطلاعات آن ناقص است و ممکن است با مجلهٔ «Farhang-e Rasaneh (فرهنگ رسانه)» (ردیف ۲.۹) تداخل داشته باشد. پیش از استفاده باید از داخل ایران تأیید شود و در صورت عدم‌تأیید، این مورد باید حذف شود.', 'ece0ee180d27b153841ad81c9eeec2d86d7967ef204938ba92a62a9a35a8dc68', 690, 'ch-doc-new-journal-12-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-13-0', 'doc-new-journal-13', NULL, 0, 'Journal of Media Ethics مجلهٔ بین‌المللی و Q3 (SCImago و Web of Science — Communication / Ethics) در حوزه‌ی اخلاق رسانه، اخلاق روزنامه‌نگاری، حریم خصوصی و حقوق رسانه است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «اخلاق رسانه» و پوشش‌دهنده‌ی خلأ مجلات اخلاق رسانه است. با ISSN 2373-6992 (چاپی) و 2373-700X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'b3621a94838229ed454b41fe58c95cf21058c24682c8cc5f501125953242acd8', 798, 'ch-doc-new-journal-13-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-14-0', 'doc-new-journal-14', NULL, 0, 'International Journal of Middle East Studies (IJMES) مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science — Middle Eastern / Islamic Studies) در حوزه‌ی مطالعات خاورمیانه، تاریخ خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Cambridge University Press منتشر می‌شود. این مجله مرجع اصلی «مطالعات خاورمیانه» از منظر پژوهش غربی است. با ISSN 0020-7438 (چاپی) و 1471-6380 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'd127ee0a288a1805ba2abde8f4059e6e37ac08c921a61c5075c6a661107804f8', 863, 'ch-doc-new-journal-14-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-15-0', 'doc-new-journal-15', NULL, 0, 'Middle East Journal مجلهٔ بین‌المللی و Q2 (SCImago و Web of Science — Middle Eastern Studies) در حوزه‌ی مطالعات خاورمیانه، سیاست خاورمیانه، فرهنگ خاورمیانه و رسانه خاورمیانه است که توسط Columbia University منتشر می‌شود. این مجله (بنیان‌گذاری ۱۹۴۷) مرجع اصلی «مطالعات خاورمیانه» از منظر تاریخی/سیاسی است. با ISSN 0026-3292 (چاپی) و 1548-9251 (الکترونیکی — نیازمند تأیید)، در Scopus، Web of Science و Scimago نمایه شده است؛ این مجله در CrossRef ثبت ندارد اما مجلهٔ معتبر دانشگاه کلمبیا است.', '70253844a2d5439a9764c288e3bb2b1000e80fb0b926054facb80f5382024456', 887, 'ch-doc-new-journal-15-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-2-0', 'doc-new-journal-2', NULL, 0, 'Media, Culture & Society مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی مطالعات فرهنگی رسانه، جامعه‌شناسی رسانه و رسانه و فرهنگ عامه است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی «جامعه‌شناسی رسانه» و «رسانه و فرهنگ» به‌شمار می‌رود. با ISSN 0163-4437 (چاپی) و 1460-3675 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', '04b1bb2325a594c2932cdcebe3832ce05ca268aa09a0451a3ee679b100241530', 734, 'ch-doc-new-journal-2-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-3-0', 'doc-new-journal-3', NULL, 0, 'Convergence: The International Journal of Research into New Media Technologies مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی فناوری‌های رسانه‌های نو، همگرایی رسانه‌ای، آینده‌ی رسانه و رسانه و فناوری است که توسط SAGE Publications منتشر می‌شود. این مجله مرجع اصلی پژوهش فناوری‌های رسانه‌های نو به‌شمار می‌رود. با ISSN 1354-8565 (چاپی) و 1748-7382 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'd807d7302524b3e3b13d49bd8ea77c24d88d3e8be62474d79cdfccffdb14f79d', 847, 'ch-doc-new-journal-3-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-4-0', 'doc-new-journal-4', NULL, 0, 'Journalism Studies مجلهٔ بین‌المللی و Q1 (SCImago و Web of Science) در حوزه‌ی پژوهش روزنامه‌نگاری، روزنامه‌نگاری تطبیقی، اقتصاد روزنامه‌نگاری و آینده‌ی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری تطبیقی» و «پارادایم‌های روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1461-670X (چاپی) و 1469-9699 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'e309ddaa82a2038370a6ac972b76e013a51051564249e2443cb9e1dcb81a4f7a', 823, 'ch-doc-new-journal-4-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-5-0', 'doc-new-journal-5', NULL, 0, 'Digital Journalism مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی روزنامه‌نگاری دیجیتال، روزنامه‌نگاری داده‌محور، رسانه‌های اجتماعی و خبر، الگوریتم و خبر است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «روزنامه‌نگاری دیجیتال» و «روزنامه‌نگاری خودکار» است و پوشش دقیقی از مدخل‌های پلتفرمی سایت ارائه می‌دهد. با ISSN 2167-0811 (چاپی) و 2167-082X (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', '4a44c4c2119a04a8cfd6df772dc0e5e60f313c44bd27fe3f85c7d21381cf7f58', 892, 'ch-doc-new-journal-5-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-6-0', 'doc-new-journal-6', NULL, 0, 'Journalism Practice مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی عمل روزنامه‌نگاری، اخلاق روزنامه‌نگاری، رسانه‌های اجتماعی و خبر و پژوهش عملی روزنامه‌نگاری است که توسط Informa UK (Taylor & Francis) منتشر می‌شود. این مجله مرجع اصلی «عمل روزنامه‌نگاری» و «اخلاق روزنامه‌نگاری» به‌شمار می‌رود. با ISSN 1751-2786 (چاپی) و 1751-2794 (الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', 'f0174336715482e1a27e3e0f435f97994faa12a9d9806a3825cf9f40ff052dfc', 818, 'ch-doc-new-journal-6-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-7-0', 'doc-new-journal-7', NULL, 0, 'International Journal of Communication (IJOC) مجلهٔ بین‌المللی و Q1/Q2 (SCImago و Web of Science) در حوزه‌ی پژوهش ارتباطات بین‌المللی، روش‌شناسی ارتباطات، ارتباطات و فناوری است که توسط USC Annenberg Press به‌صورت رایگان (Open Access) منتشر می‌شود. این مجله مرجع اصلی «روش‌شناسی ارتباطات» و «ارتباطات محاسباتی» به‌شمار می‌رود. با ISSN 1932-8036 (فقط الکترونیکی)، در Scopus، Web of Science و Scimago نمایه شده و داده‌های آن از CrossRef اعتبارسنجی شده است.', '1ec35ffe3ff7d195f8196c4a9eaed71df9107e3c1cb2932c8d44c6871e6e8694', 823, 'ch-doc-new-journal-7-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-8-0', 'doc-new-journal-8', NULL, 0, 'Peyam (پیام) — پژوهش‌های علوم انسانی مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی علوم انسانی، ارتباطات، جامعه‌شناسی و فرهنگ است که توسط پژوهشگاه علوم انسانی و مطالعات فرهنگی منتشر می‌شود. این مجله مرجع اصلی «ارتباطات در بافت ایران» به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در DOAJ/CrossRef/Wikidata، ISSN و وضعیت نمایه‌ی بین‌المللی (Scopus/ESCI) هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', 'b0956ee200fe3b75f1a47d503e0a3c4db74d2dd36e3380eb4ac08a1f265242ce', 861, 'ch-doc-new-journal-8-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-journal-9-0', 'doc-new-journal-9', NULL, 0, 'Farhang-e Rasaneh (فرهنگ رسانه) مجلهٔ معتبر و شناخته‌شده‌ی ایرانی در حوزه‌ی فرهنگ رسانه، مطالعات فرهنگی و ارتباطات است که توسط پژوهشگاه فرهنگ، هنر و ارتباطات منتشر می‌شود. این مجله مرجع اصلی «فرهنگ رسانه» در بافت ایرانی به‌شمار می‌رود. به‌دلیل درنبررس‌نبودن وبسایت‌های ایرانی از خارج ایران و عدم‌وجود در پایگاه‌های بین‌المللی، ISSN و وضعیت نمایه‌ی بین‌المللی هنوز تأیید نشده است و پیش از استفاده باید از داخل ایران در نورمگز/مگیران/ساین تأیید شود.', '07dbf62741287a576e1a524b10efe0eda9134b30ba59797e1eaf295cf789c789', 812, 'ch-doc-new-journal-9-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-1-0', 'doc-new-theorist-1', NULL, 0, 'علی شریعتی (۱۹۳۳–۱۹۷۷) جامعه‌شناس، فیلسوف و پژوهشگر ایرانی با مدرک دکترای جامعه‌شناسی از دانشگاه پاریس است. او از مهم‌ترین نظریه‌پردازان ایرانیِ «بازگشت به اصل» و تحلیل انتقادی رسانه و فرهنگ در بافت اسلامی به‌شمار می‌رود. از آثار کلیدی او می‌توان به «مسلمان من»، «سنت و مدرنیته» و «ایدئولوژی سلطه‌گر» اشاره کرد.', 'a522c86f3560a7250b0198bf1d2f152bddb16ce832effde27a360bec51d83924', 565, 'ch-doc-new-theorist-1-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-10-0', 'doc-new-theorist-10', NULL, 0, 'خوزه وان دیک نویسنده‌ی برجسته‌ی مطالعات رسانه و ارتباطات در دانشگاه اوترخت است. او مرجع اصلی مطالعات «جامعه‌ی پلتفرمی» است. آثار کلیدی او شامل «The Culture of Connectivity» (2013)، «The Platform Society» (2019) و «Tracing Twitter» (2013) است.', '7401f24ca054d9149abd4763f144b2f1932b88f066f07841f5e4d3137ca71e26', 439, 'ch-doc-new-theorist-10-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-11-0', 'doc-new-theorist-11', NULL, 0, 'اولیس میخیاس پژوهشگر در دانشکده‌ی ارتباطات دانشگاه جورج ماسون است. او بنیان‌گذار مفهوم «استعمار داده» (Data Colonialism) و پلی میان خلأ دیجیتال و خلأ پسااستعماری به‌شمار می‌رود. آثار کلیدی او شامل «Data Colonialism» (2018) و «A Decolonial Data Ethics» (2018) است.', '7ed14929d07f65014a69e6d240a4bedbebbc3b213c3b135cd9c9d679c9ef7891', 478, 'ch-doc-new-theorist-11-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-12-0', 'doc-new-theorist-12', NULL, 0, 'مارک اندرژویچ پژوهشگر در دانشکده‌ی ارتباطات و رسانه‌ی دانشگاه سیدنی است. او نظریه‌پرداز اصلی «نظارت دیجیتال» و اقتصاد داده‌ای است. آثار کلیدی او شامل «Reality TV» (2008)، «The Work of Networks» (2013) و «Proximity Media» (2020) است.', 'd50ba6bdc3eb5f36ebb914e28cc25655a94d0f7715e896c464bd8a920dcdf44f', 421, 'ch-doc-new-theorist-12-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-13-0', 'doc-new-theorist-13', NULL, 0, 'ویکتور مایر-شونبرگر پژوهشگر در مؤسسه‌ی اینترنت آکسفورد است. او مرجع اصلی «حقوق بزرگ‌داده» و «حق فراموش‌شدن» است. آثار کلیدی او شامل «Big Data: A Revolution That Will Transform Us» (2013) و «Delete» (2018) است.', '5eafecfe68eb2b1c99d1b08edead1d572dfa3d37cc6ced1709b2c4d35d002694', 379, 'ch-doc-new-theorist-13-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-14-0', 'doc-new-theorist-14', NULL, 0, 'شوشانا زبوف پژوهشگر در مدرسه‌ی کندی هاروارد است. او بنیان‌گذار مفهوم «اقتصاد نظارتی» (Surveillance Capitalism) و مرجع اصلی خلأ دیجیتال و اخلاق/تنظیم به‌شمار می‌رود. اثر کلیدی او «The Age of Surveillance Capitalism» (2019) است.', '52fd5e6f64d7fa42dc613767b5a7203991feda7552ac1233d3a6a85e70ab3b23', 410, 'ch-doc-new-theorist-14-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-15-0', 'doc-new-theorist-15', NULL, 0, 'کیان تجب‌خواه پژوهشگر رسانه و دین/میانه‌شرق در دانشگاه کالیفرنیا است. او به رسانه در جهان اسلام و رسانه و سیاست میانه‌شرق می‌پردازد. اثر کلیدی او «Media in the Islamic World: Introduction» (Social Research, 2003) است.', 'd09e5ffaab5cb515ffcc9506c4b1ccfb7b21beab3f83ec68fb7fb35166a217af', 394, 'ch-doc-new-theorist-15-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-16-0', 'doc-new-theorist-16', NULL, 0, 'مهدی سِمتی پژوهشگر رسانه و سیاست در ایران است. او به فناوری‌های رسانه و سیاست در ایران می‌پردازد و پژوهشگر ایرانیِ قابل‌تأیید با DOI است. اثر کلیدی او فصل «Media Technologies and Politics in Iran» در کتاب «The Handbook of Media and Culture in the Middle East» (2023) است.', '4d45130a28833b0c0d325741b8c87fd35c706a36be9fbcf343b9e8ccab64827b', 492, 'ch-doc-new-theorist-16-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-17-0', 'doc-new-theorist-17', NULL, 0, 'کیان وهبه پژوهشگر مطالعات خاورمیانه و رسانه در دانشگاه تورنتو است. او به رسانه و میانه‌شرق و سانسور رسانه‌ای می‌پردازد. توجه: نام او در Crossref با چندین «Wehbe» دیگر (پزشک/مهندسی) در تضاد است و آثار رسانه‌ایِ مشخصی به‌راحتی یافت نشد؛ تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', '1706fe5f76b982d98d3bdb99b930136a686b8643a7b36a8d527fee219ae02b62', 509, 'ch-doc-new-theorist-17-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-18-0', 'doc-new-theorist-18', NULL, 0, 'ناصر عباس‌پور پژوهشگر رسانه و سیاست در ایران است. او به سیاست رسانه و رسانه در ایران می‌پردازد و مقالاتی درباره‌ی سیاست رسانه در ایران در مجلات معتبر منتشر کرده است. توجه: در فهرست قبلی با علامت «نیازمند بررسی» ثبت شده بود و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', '3e3a75e8fa4686f751ac3f480e1861adb28eb5e4fe653df45a7a9df0ca092eaa', 490, 'ch-doc-new-theorist-18-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-19-0', 'doc-new-theorist-19', NULL, 0, 'سارا طالبیان پژوهشگر رسانه و سیاست در مجله‌ی Global Media and Communication است. او به سیاست رسانه پخش در ایران می‌پردازد. اثر کلیدی او «Iran''s Broadcasting Policy» (Global Media and Communication, 2020) است.', '877631915013c728ab026ec51bf404889200bd757b154294ea778cf8183f98ad', 378, 'ch-doc-new-theorist-19-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-2-0', 'doc-new-theorist-2', NULL, 0, 'فاتیمه مرنسی (۱۹۴۰–۲۰۱۵) جامعه‌شناس و پژوهشگر مغربی بود که در دانشکده‌ی مطالعات خاورمیانه و آفریقا دانشگاه ایالتی اوهایو تدریس می‌کرد. او بنیان‌گذار «فمینیسم اسلامی» است و به تحلیل انتقادی رسانه و گفتمان در جوامع اسلامی پرداخته است. از آثار کلیدی او «The Veil and the Male Elite» (1991)، «Islam and Women: Religious Writings» (1993) و «Dreams of Trespass» (2001) است.', '19c184689036ae5704812e158169821f5fccafe0d9b32c452ada11fb23f3fa7b', 667, 'ch-doc-new-theorist-2-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-20-0', 'doc-new-theorist-20', NULL, 0, 'دیوید م. فاریس پژوهشگر شبکه‌های اجتماعی و خاورمیانه در دانشگاه کارنگی ملون است که با هم‌نویس ایرانی‌اش Babak Rahimi همکاری می‌کند. او مرجع اصلی «شبکه‌های اجتماعی و خاورمیانه» است. اثر کلیدی او «The New Arab Activism» (2015) است.', '8312a1e4204cec93fece8992e0ce15928722dcf07bc5628e27eae77ffa73782e', 414, 'ch-doc-new-theorist-20-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-3-0', 'doc-new-theorist-3', NULL, 0, 'علی شادید پژوهشگر رسانه و اسلام در هلند است. او پیشگام پژوهش «رسانه و اسلام» و تحلیل تصویرسازی رسانه‌ای غرب از اسلام و مسلمانان‌هاست. آثار کلیدی او شامل «Berichtgeving over moslims en de islam in de westerse media: Beeldvorm» (1996) و «Muslims and the Media» (2005) است.', '3c46d99bf15460e6d7b49bee01405d242ed0db9c34543c6ec553a6978ad252f2', 490, 'ch-doc-new-theorist-3-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-4-0', 'doc-new-theorist-4', NULL, 0, 'هانی خمیس پژوهشگر رسانه و رسانه‌های اسلامی در دانشگاه لندن شرقی است. او مرجع اصلی مطالعات «رسانه در جهان اسلامی» است و به اقتصاد رسانه و رسانه و سیاست در جهان اسلام پرداخته است. از آثار کلیدی او می‌توان به فصل‌های متعددی در مجموعه‌های معتبر درباره‌ی «Media in the Islamic World» اشاره کرد.', '6cb98e16449f15ad2e90b5ba8f4ac0046b597cc6c696701f0766f99e4425d179', 525, 'ch-doc-new-theorist-4-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-5-0', 'doc-new-theorist-5', NULL, 0, 'حسن حبیب پژوهشگر رسانه در حوزه‌ی لبنان و خاورمیانه است که در مجله‌ی Communications & Strategies منتشر کرده است. او به رسانه در خاورمیانه و رابطه‌ی رسانه و سیاست می‌پردازد. اثر کلیدی او «Lebanon... Notwithstanding» (Communications & Strategies) است. توجه: نام او در Crossref با «Hasan Habib» بازیکن پوکر در تضاد است و تأیید نهایی از وب‌سایت دانشگاهی توصیه می‌شود.', '0ea05e2ddf4990e658e791302646621a647e65897548927332278b8292e83a89', 658, 'ch-doc-new-theorist-5-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-6-0', 'doc-new-theorist-6', NULL, 0, 'عبداللهی آن‌نعیم استاد حقوق در دانشگاه اموری (Stewart McKelvey Professor of Law) است. او مهم‌ترین نظریه‌پرداز «حقوق بشر از دیدگاه اسلامی» و پل ارتباطی میان خلأ حقوق رسانه و خلأ اسلامی به‌شمار می‌رود. از آثار کلیدی او «Islam and Human Rights: Beyond the Universality Debate» (1992) و «Toward an Islamic Reformation» (2008) است.', '25924e33c9cd88ad98ca4539effbee191e69b65f66fc49f4b89c335f24a95dfc', 592, 'ch-doc-new-theorist-6-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-7-0', 'doc-new-theorist-7', NULL, 0, 'یاسمین مولانا پژوهشگر رسانه و محیط‌زیست در دانشگاه فرا (ایتالیا) است. او یکی از معدود نظریه‌پردازان ایرانیِ قابل‌تأیید با DOI است (هم‌نویس مقاله‌ی MDPI 2026) و به روزنامه‌نگاری پایدار و محیطی و رسانه در ایران می‌پردازد. اثر کلیدی او «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) است که با Mehrdad Ahmadi و Antonio López هم‌نویسی شده است.', 'af46331ef552bf746b13fd04616b5561a8b490ac3dbada6fb06800fa5a4d9e22', 761, 'ch-doc-new-theorist-7-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-8-0', 'doc-new-theorist-8', NULL, 0, 'مهرداد احمدی پژوهشگر ایرانی در حوزه‌ی ارتباطات محیطی و رسانه و توسعه پایدار است. او هم‌نویس مقاله‌ی «Conceptualizing Sustainable Media: An Integrated Model for Environmental Journalism in Iran» (Journalism and Media, MDPI 2026) با Yasamin Molana و Antonio López است و دومین نظریه‌پرداز ایرانیِ قابل‌تأیید با DOI به‌شمار می‌رود.', 'e1713af72bb84785ad5cfcc40675a51dbf737cfa767b9b700c5e6eff450d7772', 594, 'ch-doc-new-theorist-8-0', 'Qwen3-Embedding-4B', 'v1');
INSERT IGNORE INTO `ai_chunks` (`id`, `document_id`, `section_id`, `chunk_index`, `content`, `content_hash`, `token_count`, `vector_point_id`, `embedding_model`, `embedding_version`) VALUES ('ch-doc-new-theorist-9-0', 'doc-new-theorist-9', NULL, 0, 'دانا بوید پژوهشگر ارتباطات و فناوری در دانشگاه کورنل است. او یکی از برجسته‌ترین نظریه‌پردازان دیجیتال و پلتفرم پس از سال ۲۰۰۰ است. آثار کلیدی او شامل «It''s Complicated: The Social Lives of Networked Teens» (2014) و «Zuckerberg''s Dilemma» (2015) است.', '36901bd40e8908a715266a40d0a767aaaa9d97314dad1774bd9da061b948d214', 452, 'ch-doc-new-theorist-9-0', 'Qwen3-Embedding-4B', 'v1');
